#include <vector>
#include <array>
#include <algorithm>
#include <omp.h>

/*
   Count how many values of `x` fall into each decile:
        [0,10), [10,20), … , [90,100]   (the value 100 is placed in the last bin)
   The result is stored in `bins`, which must contain exactly 10 elements.
   The computation is performed in parallel with OpenMP and works correctly for
   any number of threads.
*/
void binsBy10Count(const std::vector<double>& x,
                   std::array<std::size_t, 10>& bins)
{
    // Initialise the output bins.
    bins.fill(0);

    // Each thread will accumulate its own private copy of the bins.
    // After the parallel loop we combine the private copies into the shared
    // result using a critical section (the amount of work is tiny, so the
    // overhead is negligible).
    #pragma omp parallel
    {
        std::array<std::size_t, 10> local_bins;
        local_bins.fill(0);

        #pragma omp for schedule(static)
        for (std::size_t i = 0; i < x.size(); ++i) {
            // Determine the bin index.  Values exactly equal to 100 go to the
            // last bin (index 9).  Clamp to the valid range [0,9] for safety.
            int idx = static_cast<int>(x[i] / 10.0);
            idx = std::min(idx, 9);
            idx = std::max(idx, 0);
            ++local_bins[idx];
        }

        // Merge this thread's local histogram into the global one.
        #pragma omp critical
        {
            for (std::size_t j = 0; j < 10; ++j) {
                bins[j] += local_bins[j];
            }
        }
    }
}
